package com.volna.profile_service.service;import com.volna.profile_service.dto.*;import com.volna.profile_service.exception.ResourceNotFoundException;import com.volna.profile_service.entity.*;import com.volna.profile_service.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;@Service @Transactional public class ProfileService{private final RestaurantProfileRepository profiles;private final ProfileRestaurantAccessRepository access;public ProfileService(RestaurantProfileRepository p,ProfileRestaurantAccessRepository a){profiles=p;access=a;}private UUID restaurant(UUID user){return access.findByAuthUserId(user).map(ProfileRestaurantAccess::getRestaurantId).orElseThrow(()->new ResourceNotFoundException("Restaurant access not configured for authenticated user"));}public ProfileResponse get(UUID user){UUID r=restaurant(user);return profiles.findByRestaurantId(r).map(this::map).orElseGet(()->new ProfileResponse(null,r,"","","","","","","","","","","","",null,null,true));}public ProfileResponse update(UUID user,ProfileUpdateRequest q){UUID r=restaurant(user);RestaurantProfile x=profiles.findByRestaurantId(r).orElseGet(()->{RestaurantProfile n=new RestaurantProfile();n.setRestaurantId(r);return n;});x.setRestaurantName(q.getRestaurantName());x.setCuisineType(q.getCuisineType());x.setDescription(q.getDescription());x.setPhone(q.getPhone());x.setEmail(q.getEmail());x.setWebsite(q.getWebsite());x.setAddress(q.getAddress());x.setCity(q.getCity());x.setState(q.getState());x.setPostalCode(q.getPostalCode());x.setCountry(q.getCountry());x.setLogoUrl(q.getLogoUrl());x.setOpeningTime(q.getOpeningTime());x.setClosingTime(q.getClosingTime());if(q.getActive()!=null)x.setActive(q.getActive());return map(profiles.save(x));}private ProfileResponse map(RestaurantProfile x){return new ProfileResponse(x.getId(),x.getRestaurantId(),x.getRestaurantName(),x.getCuisineType(),x.getDescription(),x.getPhone(),x.getEmail(),x.getWebsite(),x.getAddress(),x.getCity(),x.getState(),x.getPostalCode(),x.getCountry(),x.getLogoUrl(),x.getOpeningTime(),x.getClosingTime(),x.isActive());}}
